    "file": "date_safe.htm",
    "slug": "date-safely",
    "title": "Date Safely",
    "category": "Dating Advice",
    "description": "Common-sense safety reminders for meeting new people through dating sites, singles events, and introductions.",
    "legacyPath": "date_safe.htm",
